#include <array>
#include <cassert>
#include <cstdint>
#include <cstdio>
#include <fstream>
#include <vector>
#include "sm121_integer_parts.h"
constexpr unsigned tokens=7169, qheads=16, kvheads=2, dim=256;
using Row=std::array<uint16_t,18>;
std::vector<uint16_t> read(const char* path,size_t size){
 std::ifstream f(path,std::ios::binary|std::ios::ate);assert(f&&size_t(f.tellg())==size*2);
 std::vector<uint16_t> v(size);f.seekg(0);f.read(reinterpret_cast<char*>(v.data()),size*2);assert(f);return v;
}
int range(const Row& r){
 int lo=1000,hi=0;
 for(unsigned i=0;i<16;++i){uint16_t v=r[i];if(!(v&0x7fff))continue;
  unsigned e=(v>>7)&255; if(e==0||e==255)return 256;
  int unit=int(e)+int(qrt_sm121_integer_parts::trailing_bits(128u|(v&127)));
  if(unit<lo)lo=unit;if(int(e)>hi)hi=int(e);
 }
 return lo==1000 ? -8 : hi-lo;
}
Row contiguous(const std::vector<uint16_t>& v,size_t row){Row r{};for(unsigned i=0;i<16;++i)r[i]=v[row*16+i];return r;}
void print_hist(const char* name,const std::vector<uint16_t>& v,bool transposed){
 uint64_t hist[265]{};size_t n=transposed?((tokens+31)/32)*2*kvheads*dim:v.size()/16;
 for(size_t row=0;row<n;++row){Row r{};
  if(!transposed)r=contiguous(v,row);
  else {size_t group_head=row/dim; for(unsigned i=0;i<16;++i){size_t t=(group_head/kvheads)*16+i;
    if(t<tokens)r[i]=v[(t*kvheads+group_head%kvheads)*dim+row%dim];}}
  ++hist[range(r)+8];
 }
 std::printf("\"%s\":{\"rows\":%zu,\"unit_exponent_span_histogram\":{",name,n);
 bool first=true;for(int i=0;i<265;++i)if(hist[i]){std::printf("%s\"%d\":%llu",first?"":",",i-8,(unsigned long long)hist[i]);first=false;}
 std::printf("}}");
}
unsigned rng=0x8192395u;
unsigned random_word(){rng^=rng<<13;rng^=rng>>17;rng^=rng<<5;return rng;}
int main(int argc,char** argv){assert(argc==4);
 auto q=read(argv[1],size_t(tokens)*qheads*dim),k=read(argv[2],size_t(tokens)*kvheads*dim),v=read(argv[3],size_t(tokens)*kvheads*dim);
 std::printf("{\"schema_version\":1,\"sample_seed\":%u,\"row_distributions\":{",rng);
 print_hist("query",q,false);std::printf(",");print_hist("key",k,false);std::printf(",");print_hist("value",v,true);
 constexpr unsigned samples=1048576;uint64_t eligible16=0,eligible24=0,old_fast_zero_carry=0;
 uint64_t paired_hist[265]{};
 for(unsigned s=0;s<samples;++s){unsigned qt=random_word()%tokens,kt=random_word()%(qt+1),qh=random_word()%qheads,g=random_word()%16;
  auto a=contiguous(q,(size_t(qt)*qheads+qh)*16+g),b=contiguous(k,(size_t(kt)*kvheads+qh/8)*16+g);
  int ar=range(a),br=range(b),r=ar>br?ar:br;++paired_hist[r+8];eligible16+=r<=7;eligible24+=r<=15;
  uint16_t aa[18]{},bb[18]{};for(unsigned i=0;i<16;++i){aa[i]=a[i];bb[i]=b[i];}
  int amax,bmax;int amin=qrt_sm121_integer_parts::row_unit_range(aa,&amax),bmin=qrt_sm121_integer_parts::row_unit_range(bb,&bmax);
  uint32_t at[4]{},bt[4]{};int32_t partials[4]{};
  for(unsigned i=0;i<16;++i){uint16_t av=qrt_sm121_integer_parts::encode(aa[i],amin),bv=qrt_sm121_integer_parts::encode(bb[i],bmin);
   at[i/4]|=qrt_sm121_integer_parts::trailing_bits(av)<<((i%4)*8);bt[i/4]|=qrt_sm121_integer_parts::trailing_bits(bv)<<((i%4)*8);
   int ah=int(av>>8),bh=int(bv>>8),al=av&255,bl=bv&255;if(ah>=128)ah-=256;if(bh>=128)bh-=256;
   partials[0]+=ah*bh;partials[1]+=ah*bl;partials[2]+=al*bh;partials[3]+=al*bl;
  }
  qrt_sm121_group16::AlignedSum sum{};
  old_fast_zero_carry+=qrt_sm121_integer_parts::sum_exact_range({0,-133,false},partials,amin,amax,bmin,bmax,&sum,at,bt);
 }
 std::printf("},\"causal_query_key_sample\":{\"groups\":%u,\"eligible_signed16\":%llu,\"eligible_signed24\":%llu,\"existing_fast_bound_with_zero_carry\":%llu,\"paired_maximum_span_histogram\":{",samples,(unsigned long long)eligible16,(unsigned long long)eligible24,(unsigned long long)old_fast_zero_carry);
 bool first=true;for(int i=0;i<265;++i)if(paired_hist[i]){std::printf("%s\"%d\":%llu",first?"":",",i-8,(unsigned long long)paired_hist[i]);first=false;}
 std::printf("}},\"inference_or_performance_acceptance\":false}\n");
}
